Item.method_code:
            Innovator inn = this.getInnovator();
            //権限付与用
            Aras.Server.Security.Identity adminIdentity = Aras.Server.Security.Identity.GetByName("Administrators");
            
            try
            {
                //①保存時、h4_ApprovalWFGroup_ApTargetタブに複数アイテムタイプの種類があるかチェックする。あったらエラー
                //②他の一括承認に紐づいていたらエラー
                //③WFの有無が0の場合、エラー
                //④ステートが承認済みの場合エラー
                //⑤ステートが承認却下のときエラー(必要資料のみ)
                //⑥やるやらが×の時はエラー(必要資料のみ)

                var thisId = this.getID();
                var thisConfigId = this.getProperty("config_id", thisId);
                var thisType = this.getType();
                
                List<string> stateList = new List<string> {"Approved","Unapproved"};

                string type = "";
                
                var relItemNames = "h4_ApprovalWFGroup_ApTarget";
                this.fetchRelationships(relItemNames);
                var relationships = this.getRelationships(relItemNames);
                var count = relationships.getItemCount();
                
                for (var i = 0; i < count; i++)
                {
                    var relationship = relationships.getItemByIndex(i);
                
                    if("delete" == relationship.getAction())
                    {
                        continue;
                    }
                    
                    var RelatedItem =  relationship.getRelatedItem();
                     
                    if(RelatedItem == null)
                    {
                        continue;
                    }

                    //①のチェック
                    var getType = RelatedItem.getType();
                    
                    if(!string.IsNullOrEmpty(getType))
                    {
                        if(string.IsNullOrEmpty(type))
                        {
                            type = getType;
                        }
                        if(type != getType)
                        {
                            return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0801"));
                        }
                    }

                    //②のチェック
                    var relatedItemID = RelatedItem.getID();
                    var keyed_name = RelatedItem.getProperty("keyed_name","");
                    var getItems = inn.newItem(relItemNames,"get");
                    getItems.setProperty("related_id",relatedItemID);
                    getItems.setAttribute("select","id,source_id");
                    getItems.setProperty("source_id",thisId);
                    getItems.setPropertyAttribute("source_id", "condition", "ne");
                    using (CCO.Permissions.GrantIdentity(adminIdentity))
                    {
                        getItems = getItems.apply();
                        if(getItems.isError() && getItems.getItemCount() == -1)
                        {
                            return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
                        }
                    }
                    
                    if(getItems.getItemCount() > 0)
                    {
                        //子アイテムが紐づいている一括を取得
                        //※バージョン管理有効時、自分自身の旧バージョンが source_id として残るため
                        //  config_id が一致するもの（同一アイテムの別バージョン）は除外する
                        var retSourceKeyName = new List<string>();
                        for(int getItemsCount = 0;getItems.getItemCount() > getItemsCount; getItemsCount++)
                        {
                            var currSorceItemID = getItems.getItemByIndex(getItemsCount).getProperty("source_id","");
                            var currSorceItem = inn.newItem(thisType,"get");
                            currSorceItem.setID(currSorceItemID);
                            currSorceItem.setAttribute("select","keyed_name,config_id,is_current");
                            using (CCO.Permissions.GrantIdentity(adminIdentity))
                            {
                                currSorceItem = currSorceItem.apply();
                                if(currSorceItem.isError())
                                {      
                                    return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
                                }
                            }
                            // 現行版のみ重複対象とする（旧版由来の関連は除外）
                            if(currSorceItem.getProperty("is_current","") != "1")
                            {
                                continue;
                            }
                            // 自分自身の旧バージョンは除外
                            if(currSorceItem.getProperty("config_id","") == thisConfigId)
                            {
                                continue;
                            }
                            retSourceKeyName.Add(currSorceItem.getProperty("keyed_name",""));
                        }

                        if(retSourceKeyName.Count > 0)
                        {
                            return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0804",keyed_name,string.Join("<br>", retSourceKeyName)));
                        }
                    }

                    //③のチェック
                    var h4_approve_style = RelatedItem.getProperty("h4_approve_style","");

                    if(h4_approve_style == "0")
                    {
                        return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0805",keyed_name));
                    }

                    //④,⑤のチェック
                    var state = RelatedItem.getProperty("state","");

                    if (stateList.Contains(state))
                    {
                        return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0806",keyed_name));
                    }
                    
                    //⑥のチェック
                    var h4_yryr = RelatedItem.getProperty("h4_yryr","");

                    if(h4_yryr == "0")
                    {
                        return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0807",keyed_name));
                    }
                    
                }

                return this;
            }
            catch (Exception)
            {
                // Item err = inn.newError("Error:" + e.Message);
                // err.setErrorDetail(e.StackTrace);
                // return err;
                return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
            }
        }

        internal void Dummy()
        {
